TWComponent.script:
//this script make the folder path of attachment

tw.local.ODCRequest.attachmentDetails = {};
tw.local.ODCRequest.attachmentDetails.ecmProperties = {};

if(tw.local.ODCRequest.BasicDetails.requestType == tw.epv.RequestType.Create+"")
{	
	if (tw.local.ODCRequest.appInfo.status == tw.epv.Status.Canceled+"" || tw.local.ODCRequest.appInfo.status == tw.epv.Status.terminated+"") {
		tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.requestNo+"ODC/Canceled Cases"+"/Issuance";
	}else{

		tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.requestNo+"ODC"+"/Issuance";
	//	tw.local.parentPath = tw.env.FILENET_ROOT_PATH+"/"+ tw.local.ODCRequest.CustomerInfo.cif+"/DC Outward/"+tw.local.ODCRequest.requestNo+"ODC";
	}
}

//	tw.local.parentPath= tw.env.FILENET_ROOT_PATH+"/"+ tw.local.ODCRequest.CustomerInfo.cif+"/DC Outward/"+tw.local.ODCRequest.parentRequestNo+"ODC";
	
if(tw.local.ODCRequest.BasicDetails.requestType == ""+tw.epv.RequestType.Amendment){
	if (tw.local.ODCRequest.appInfo.status == tw.epv.Status.Canceled+"" || tw.local.ODCRequest.appInfo.status == tw.epv.Status.terminated+"") {
	tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.BasicDetails.parentRequestNo+"ODC/Canceled Cases"+"/Amendment "+tw.local.ODCRequest.requestNo;
	}
	else{
		tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.BasicDetails.parentRequestNo+"ODC"+"/Amendment "+tw.local.ODCRequest.requestNo;
	}
}
if(tw.local.ODCRequest.BasicDetails.requestType == ""+tw.epv.RequestType.Recreate){
	if (tw.local.ODCRequest.appInfo.status == tw.epv.Status.Canceled+"" || tw.local.ODCRequest.appInfo.status == tw.epv.Status.terminated+"") {
		tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.BasicDetails.parentRequestNo+"ODC/Canceled Cases"+"/Recreate "+tw.local.ODCRequest.requestNo;
	}
	else{
		tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.BasicDetails.parentRequestNo+"ODC"+"/Recreate "+tw.local.ODCRequest.requestNo;
	}
}
if(tw.local.ODCRequest.BasicDetails.requestType == ""+tw.epv.RequestType.Collection){
	if (tw.local.ODCRequest.appInfo.status == tw.epv.Status.Canceled+"" || tw.local.ODCRequest.appInfo.status == tw.epv.Status.terminated+"") {
		tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.BasicDetails.parentRequestNo+"ODC/Canceled Cases"+"/Collection "+tw.local.ODCRequest.requestNo;
	}
	else{
		tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.BasicDetails.parentRequestNo+"ODC"+"/Collection "+tw.local.ODCRequest.requestNo;
	}
}
if(tw.local.ODCRequest.BasicDetails.requestType == ""+tw.epv.RequestType.Closure){
	if (tw.local.ODCRequest.appInfo.status == tw.epv.Status.Canceled+"" || tw.local.ODCRequest.appInfo.status == tw.epv.Status.terminated+"") {
		tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.BasicDetails.parentRequestNo+"ODC/Canceled Cases"+"/Closure "+tw.local.ODCRequest.requestNo;
	}
	else{
		tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.BasicDetails.parentRequestNo+"ODC"+"/Closure "+tw.local.ODCRequest.requestNo;
	}
}
if(tw.local.ODCRequest.BasicDetails.requestType == ""+tw.epv.RequestType.Reversal){
	if (tw.local.ODCRequest.appInfo.status == tw.epv.Status.Canceled+"" || tw.local.ODCRequest.appInfo.status == tw.epv.Status.terminated+"") {
		tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.BasicDetails.parentRequestNo+"ODC/Canceled Cases"+"/Reversal "+tw.local.ODCRequest.requestNo;
	}
	else{
		tw.local.ODCRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.ODCRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.ODCRequest.BasicDetails.parentRequestNo+"ODC"+"/Reversal "+tw.local.ODCRequest.requestNo;
	}
}

tw.local.sqlStatements = new tw.object.listOf.SQLStatement();
var j = 0;
var i = 0;
function paramInit (value) {
	tw.local.sqlStatements[j].parameters[i] = new tw.object.SQLParameter();
	tw.local.sqlStatements[j].parameters[i].value = value;
	i++;
}
var final = "" + tw.epv.RequestState.Final;
var collected = ""+ tw.epv.RequestState.Collection;
var completed = ""+tw.epv.Status.completed;



//------------------------------------- Get invoice --------------------------------------------

tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT  INVOICENO, INVOICEDATE FROM "+ tw.env.LKP_DB_Schema +".ODC_INVOICE WHERE REQUESRID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);

////------------------------------------- Get bills --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT BILLOFLADINGREF, BILLOFLADINGDATE FROM "+ tw.env.LKP_DB_Schema +".ODC_BILLS WHERE REQUESRID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);



////------------------------------------- Get multi tenor --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT INSTALLMENTDATE, INSTALLMENTAMOUNT, INSTALLMENTBASEDATE , INSTALLMENTTENORDAYS, REBATEAMOUNT, LIQUIDATION_AMOUNT  FROM "+ tw.env.LKP_DB_Schema +".ODC_MULTITENORDATES WHERE REQUESRID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(tw.local.requestType=="collection"){
	paramInit(tw.local.results[1].rows[0].data[15]);
}else{
	paramInit(tw.local.results[0].rows[0].data[0]);
}

////------------------------------------- Get Transactions --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql= "SELECT f.ACCOUNTNO,  f.REFERENCENO, f.POSTINGDATE,  f.VALUEDATE,  f.TRANSACTIONAMOUNT,  s.AMOUNTLINKEDINBPM,  s.AMOUNTINCURRENTREQ,  s.AMOUNTINREQCURRENCY "+
						"FROM "+tw.env.LKP_DB_Schema+".ODC_FCTRANSACTION f JOIN "+tw.env.LKP_DB_Schema+".ODC_SELECTEDTRANSACTIONS s ON f.ID = s.TRANSACTIONID WHERE s.REQUESTID = ? AND  (s.isDeleted <>'Yes' OR s.isDeleted IS NULL) "+ 
						"AND s.ID IN ( SELECT MAX(s2.ID) FROM "+ tw.env.LKP_DB_Schema +".ODC_SELECTEDTRANSACTIONS s2 WHERE s2.REQUESTID = ? GROUP BY s2.TRANSACTIONID);";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);
paramInit(tw.local.results[0].rows[0].data[0]);

//------------------------------------- Get delivery terms --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT DELIVERYTERMVALUE  FROM "+ tw.env.LKP_DB_Schema +".ODC_DELIVERYTERMS  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);
   
//------------------------------------- Get delivery terms extra --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT DELIVERYTERMEXTRA   FROM "+ tw.env.LKP_DB_Schema +".ODC_DELIVERYTERMSEXTRA  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]); 
//------------------------------------- Get payment instructions--------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT PAYMENTINSTRUCTIONSVALUE  FROM "+ tw.env.LKP_DB_Schema +".ODC_PAYMENTINSTRUCTIONS  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);
   
 //------------------------------------- Get payment instructions extra--------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT PAYMENTINSTRUCTIONSEXTRA FROM "+ tw.env.LKP_DB_Schema +".ODC_PAYMENTINSTRUCTIONSEXTRA  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]); 
 //------------------------------------- instructions--------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT INSTRUCTIONSVALUE FROM "+ tw.env.LKP_DB_Schema +".ODC_INSTRUCTIONS  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);   
 //------------------------------------- instructions extra--------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT INSTRUCTIONSEXTRA  FROM "+ tw.env.LKP_DB_Schema +".ODC_INSTRUCTIONSEXTRA  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);   
 //------------------------------------- special instructions --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT SPECIALINSTRUCTIONSVALUE   FROM  "+ tw.env.LKP_DB_Schema +".ODC_SPECIALINSTRUCTIONS  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);  
   
  //------------------------------------- special instructions extra --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT SPECIALINSTRUCTIONSEXTRA FROM "+ tw.env.LKP_DB_Schema +".ODC_SPECIALINSTRUCTIONSEXTRA  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);
//----------------------------------------------------------------------------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql = "SELECT OUTSTANDINGAMOUNT FROM "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO WHERE REQUESTNO = ?;"
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);

var i=0-1;
var j =0-1;

//request types Map
var requestTypes = new tw.object.Map();
requestTypes.put(tw.epv.RequestType.Amendment+"", tw.epv.ProcessNames.odcAmendment+"");
requestTypes.put(tw.epv.RequestType.Closure+"", tw.epv.ProcessNames.odcClosure+"");
requestTypes.put(tw.epv.RequestType.Collection+"", tw.epv.ProcessNames.odcCollection+"");
requestTypes.put(tw.epv.RequestType.Create+"", tw.epv.ProcessNames.odcCreation+"");
requestTypes.put(tw.epv.RequestType.Recreate+"", tw.epv.ProcessNames.odcRecreate+"");
requestTypes.put(tw.epv.RequestType.Reversal+"", tw.epv.ProcessNames.odcReversal+"");

function getnext () {
	i++;
	var results =null;
	if(!!tw.local.results[0]){
	 if(!!tw.local.results[0].rows[0])
	    results = tw.local.results[0].rows[0].data[i];
	 }   
	else
	    results = null;
	return results;
}

function getEachProcessData () {
