tw.local.sqlStatements[0].sql = "SELECT ID, REQUESTNO, REQUESTNATURE, REQUESTTYPE, REQUESTDATE, REQUESTSTATE, REQUESTSTATUS, PARENTREQUESTNO, FCCONTRACTNO, CONTRACTSTAGE, EXPORTPURPOSE, PAYMENTTERMS, PRODUCTCATEGORY, COMMODITYDESCRIPTION, CIF, CUSTOMERNAME, BASEDATE, VALUEDATE, TENORDAYS, TRANSITDAYS, CONTRACTMATURITYDATE, USERREF, PRODUCTCODE, PRODUCTDESC, STAGE, SOURCEREF, TRADEFOREFNO, DISCOUNT, EXTRACHARGES, OURCHARGES, AMOUNTSIGHT, AMOUNTDEFNOAVALIZATION, AMOUNTDEFAVALIZATION, COLLECTABLEAMOUNT, OUTSTANDINGAMOUNT, MATURITYDATE, MATURITYDAYS, FINANCEAPPROVALNO, HUBCODE, HUBNAME, LIQAMOUNT, LIQCURRENCY, COLLECTIONCURRENCY, STANDARDEXRATE, NEGOTIATEDEXRATE, ALLOCATEDAMOUNT, TOTALALLOCATEDAMOUNT, TRANSACTIONREFNO, CBECLASSIFICATION, SHIPMENTMETHOD, SHIPMENTDATE, REVERSALREASON, CLOSUREREASON, IMPORTERNAME, IMPORTERCOUNTRY, IMPORTERADDRESS, IMPORTERPHONENO, IMPORTERBANK, BICCODE, IBANACCOUNT, BANKCOUNTRY, BANKADDRESS, BANKPHONENO, COLLECTINGBANKREF, CURRENTSTEPNAME, SUBSTATUS, BPMINSTANCENUMBER, REQUESTCURRENCY, MAXIMUMCOLLECTIONDATE, DOCUMENTAMOUNT, ADVANCEAMOUNT, CHARGESACCOUNT, COLLECTIONACCOUNT, ISLIQUIDATED, LIQDEBITVALUEDATE, LIQCREDITVALUEDATE, LIQDEBITACCNUM, LIQCREDITACCOUNTCLASS, LIQCREDITBRANCHCODE, LIQCREDITBALANCESIGN, LIQCREDITACCOUNTCURRENCY, LIQCREDITACCOUNTBALANCE, LIQCREDITAMOUNTINACCOUNT, COUNTRYOFORIGIN, BRANCHNAME, INITIATOR, FCCONTRACTNO2, FCCONTRACTNO3, CHARGESACCOUNTCURRENCY, CHARGESACCOUNTBALANCE, COLLECTIONACCOUNTCURRENCY, COLLECTIONACCOUNTBALANCE, CUSTOMERNAMEINDOC, CUSTOMERADDRESSINDOC, FOLDERPATH,CBEGOODSCODE,GOVERNMENTCOTTON,INCOTERMS,OPERATIONTYPECODE, GOODDESTINATION, REBATEAMOUNT FROM "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO  WHERE REQUESTNO = ?";
