tw.local.sqlStatements[0].parameters[0] = new tw.object.SQLParameter();
tw.local.sqlStatements[0].parameters[0].value = tw.local.requestNo;

if(tw.local.requestType == tw.epv.RequestType.Closure || tw.local.requestType == tw.epv.RequestType.Collection || tw.local.requestType == tw.epv.RequestType.Reversal)
